CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL, disabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS product_versions (id INTEGER PRIMARY KEY, merchant_id INTEGER NOT NULL REFERENCES users(id), sku TEXT NOT NULL, display_name TEXT NOT NULL, channel TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(merchant_id, sku, channel));
CREATE TABLE IF NOT EXISTS batches (id INTEGER PRIMARY KEY, version_id INTEGER NOT NULL REFERENCES product_versions(id), code TEXT NOT NULL UNIQUE, region TEXT NOT NULL, status TEXT NOT NULL, expires_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inspections (id INTEGER PRIMARY KEY, batch_id INTEGER NOT NULL REFERENCES batches(id), reviewer_id INTEGER REFERENCES users(id), result TEXT NOT NULL, status TEXT NOT NULL, notes TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, lease_until TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS complaints (id INTEGER PRIMARY KEY, version_id INTEGER NOT NULL REFERENCES product_versions(id), batch_id INTEGER NOT NULL REFERENCES batches(id), reporter_id INTEGER NOT NULL REFERENCES users(id), region TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence (id INTEGER PRIMARY KEY, complaint_id INTEGER REFERENCES complaints(id), inspection_id INTEGER REFERENCES inspections(id), object_key TEXT NOT NULL, sha256 TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS remediation (id INTEGER PRIMARY KEY, complaint_id INTEGER NOT NULL REFERENCES complaints(id), action TEXT NOT NULL, status TEXT NOT NULL, due_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (id INTEGER PRIMARY KEY, actor_id INTEGER NOT NULL REFERENCES users(id), object_type TEXT NOT NULL, object_id INTEGER NOT NULL, action TEXT NOT NULL, result TEXT NOT NULL, request_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY, recipient_id INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_keys (key TEXT PRIMARY KEY, request_hash TEXT NOT NULL, response_json TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (id INTEGER PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, lease_until TEXT, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fulfillment_rules (id INTEGER PRIMARY KEY, version_id INTEGER NOT NULL REFERENCES product_versions(id), region TEXT NOT NULL, effective_from TEXT NOT NULL, effective_to TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(version_id, region, effective_from));
CREATE TABLE IF NOT EXISTS innovation_platforms (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, city TEXT NOT NULL, focus_area TEXT NOT NULL, planned_year INTEGER NOT NULL, budget_cents INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS platform_members (id INTEGER PRIMARY KEY, platform_id INTEGER NOT NULL REFERENCES innovation_platforms(id), user_id INTEGER NOT NULL REFERENCES users(id), member_role TEXT NOT NULL, joined_at TEXT NOT NULL, UNIQUE(platform_id, user_id));
CREATE TABLE IF NOT EXISTS platform_milestones (id INTEGER PRIMARY KEY, platform_id INTEGER NOT NULL REFERENCES innovation_platforms(id), title TEXT NOT NULL, due_at TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, completed_at TEXT, UNIQUE(platform_id, title));
CREATE TABLE IF NOT EXISTS platform_reviews (id INTEGER PRIMARY KEY, platform_id INTEGER NOT NULL REFERENCES innovation_platforms(id), reviewer_id INTEGER NOT NULL REFERENCES users(id), decision TEXT NOT NULL, notes TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(platform_id, reviewer_id));
CREATE TABLE IF NOT EXISTS platform_funding (id INTEGER PRIMARY KEY, platform_id INTEGER NOT NULL REFERENCES innovation_platforms(id), amount_cents INTEGER NOT NULL, tranche INTEGER NOT NULL, status TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, approved_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, UNIQUE(platform_id, tranche));
CREATE TABLE IF NOT EXISTS platform_reports (id INTEGER PRIMARY KEY, platform_id INTEGER NOT NULL REFERENCES innovation_platforms(id), report_year INTEGER NOT NULL, summary TEXT NOT NULL, status TEXT NOT NULL, submitted_by INTEGER NOT NULL REFERENCES users(id), submitted_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(platform_id, report_year));
CREATE INDEX IF NOT EXISTS idx_platform_status ON innovation_platforms(status, planned_year);
CREATE INDEX IF NOT EXISTS idx_platform_milestones_due ON platform_milestones(status, due_at);
CREATE INDEX IF NOT EXISTS idx_platform_reports_year ON platform_reports(report_year, status);
